using CourseManagementSystem.Data; using CourseManagementSystem.DTOs.Enrollments; using CourseManagementSystem.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace CourseManagementSystem.Controllers; [ApiController][Route("api/[controller]")] public class EnrollmentsController(ApplicationDbContext context):ControllerBase{
[HttpGet] public async Task<ActionResult<IEnumerable<EnrollmentResponseDto>>> GetAll()=>Ok(await Query().OrderByDescending(x=>x.EnrollmentDate).ToListAsync());
[HttpGet("{id:int}")] public async Task<ActionResult<EnrollmentResponseDto>> GetById(int id){var x=await Query().FirstOrDefaultAsync(x=>x.Id==id);return x is null?NotFound():Ok(x);}
[HttpPost] public async Task<ActionResult<EnrollmentResponseDto>> Create(EnrollmentCreateDto dto){var error=await ValidateRefs(dto.StudentId,dto.CourseId);if(error is not null)return BadRequest(new{message=error});if(await context.Enrollments.AnyAsync(e=>e.StudentId==dto.StudentId&&e.CourseId==dto.CourseId))return Conflict(new{message="Student is already enrolled in this course."});var x=new Enrollment{StudentId=dto.StudentId,CourseId=dto.CourseId,EnrollmentDate=dto.EnrollmentDate,Status=dto.Status};context.Add(x);await context.SaveChangesAsync();var r=await Query().FirstAsync(e=>e.Id==x.Id);return CreatedAtAction(nameof(GetById),new{id=x.Id},r);}
[HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EnrollmentUpdateDto dto){var x=await context.Enrollments.FindAsync(id);if(x is null)return NotFound();var error=await ValidateRefs(dto.StudentId,dto.CourseId);if(error is not null)return BadRequest(new{message=error});if(await context.Enrollments.AnyAsync(e=>e.Id!=id&&e.StudentId==dto.StudentId&&e.CourseId==dto.CourseId))return Conflict(new{message="Student is already enrolled in this course."});x.StudentId=dto.StudentId;x.CourseId=dto.CourseId;x.EnrollmentDate=dto.EnrollmentDate;x.Status=dto.Status;await context.SaveChangesAsync();return NoContent();}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await context.Enrollments.FindAsync(id);if(x is null)return NotFound();context.Remove(x);await context.SaveChangesAsync();return NoContent();}
private IQueryable<EnrollmentResponseDto> Query()=>context.Enrollments.AsNoTracking().Select(e=>new EnrollmentResponseDto(e.Id,e.StudentId,e.Student.FullName,e.CourseId,e.Course.Title,e.EnrollmentDate,e.Status));
private async Task<string?> ValidateRefs(int studentId,int courseId){if(!await context.Students.AnyAsync(x=>x.Id==studentId))return "Student does not exist.";if(!await context.Courses.AnyAsync(x=>x.Id==courseId))return "Course does not exist.";return null;}
}
